//! Both quotation tags use the same canonical native HTML interface.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><q id=q cite=../one>Inline</q><blockquote id=block cite=/two>Block</blockquote><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://quote-interface.test/dir/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn quote_interface_both_native_tags_share_canonical_constructor_prototype_and_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var q=document.getElementById('q'),b=document.getElementById('block'),C=HTMLQuoteElement,P=C.prototype;if(!(q instanceof C)||!(b instanceof C)||Object.getPrototypeOf(q)!==P||Object.getPrototypeOf(b)!==P||P.constructor!==C||Object.getPrototypeOf(P)!==HTMLElement.prototype||Object.getPrototypeOf(C)!==HTMLElement||Object.prototype.toString.call(q)!=='[object HTMLQuoteElement]'||Object.prototype.toString.call(b)!=='[object HTMLQuoteElement]'||q.textContent!=='Inline'||b.textContent!=='Block'||q.getAttribute('cite')!=='../one'||b.getAttribute('cite')!=='/two')throw 'shared native quote interface';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal quote construction';"#);}
#[test]
fn quote_interface_inert_exact_html_names_share_interface_and_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',C=HTMLQuoteElement;for(var tag of ['q','blockquote']){var x=doc.createElementNS(html,'t:'+tag);if(!(x instanceof C)||Object.getPrototypeOf(x)!==C.prototype||x.constructor!==C||x.prefix!=='t'||x.localName!==tag)throw 'inert quote interface';var copy=x.cloneNode(false),native=document.importNode(x,false);if(!(copy instanceof C)||!(native instanceof C)||copy===x||native===x||native.ownerDocument!==document||copy.ownerDocument!==doc)throw 'actual quote copy interfaces';}for(var wrong of [doc.createElementNS('urn:foreign','q'),doc.createElementNS(html,'Q'),doc.createElementNS(html,'BLOCKQUOTE'),document.body]){if(wrong instanceof C)throw 'exact quote brand';}"#);}
#[test]
fn quote_interface_native_deep_clones_and_fallback_replacement_keep_actual_children(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var id of ['q','block']){var x=document.getElementById(id),first=x.firstChild,copy=x.cloneNode(true),attr=copy.getAttributeNode('cite'),list=copy.childNodes;copy.id='copy-'+id;document.body.appendChild(copy);if(!(copy instanceof HTMLQuoteElement)||copy.textContent!==x.textContent||copy.firstChild===first||attr===x.getAttributeNode('cite')||attr.value!==x.getAttribute('cite'))throw 'independent quote clone';copy.textContent='Changed\ud800';if(copy.textContent!=='Changed\ud800'||copy.childNodes!==list||list.length!==1||x.firstChild!==first||copy.getAttributeNode('cite')!==attr)throw 'actual quote fallback replacement';}if(document.getElementById('neighbor').value!=='seed')throw 'neighbor state';"#);}


#[test]
fn quote_interface_saved_constructor_author_properties_and_forged_node_brands(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var C=HTMLQuoteElement,P=C.prototype,q=document.getElementById('q'),b=document.getElementById('block');q.constructor='author';if(q.constructor!=='author'||Object.getPrototypeOf(q)!==P||!(q instanceof C)||b.constructor!==C)throw 'author constructor does not change canonical class';delete q.constructor;delete window.HTMLQuoteElement;if(q.constructor!==C||!(q instanceof C)||!(b instanceof C)||Object.getPrototypeOf(b)!==P)throw 'saved quote constructor';var caught=false;try{Node.prototype.cloneNode.call(Object.create(P),true);}catch(e){caught=e instanceof TypeError;}if(!caught||q.textContent!=='Inline'||b.textContent!=='Block')throw 'forged quote has no native node authority';"#);
}
#[test]
fn quote_interface_native_adoption_returns_same_node_attributes_children_and_class(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var C=HTMLQuoteElement,doc=new Document();for(var id of ['q','block']){var x=document.getElementById(id),first=x.firstChild,attr=x.getAttributeNode('cite'),list=x.childNodes;if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||!(x instanceof C)||x.constructor!==C||x.firstChild!==first||x.childNodes!==list||attr.ownerElement!==x||attr.ownerDocument!==doc)throw 'native quote adoption identity';if(document.adoptNode(x)!==x)throw 'quote return identity';document.body.appendChild(x);if(x.ownerDocument!==document||x.getAttributeNode('cite')!==attr||x.firstChild!==first||Object.getPrototypeOf(x)!==C.prototype)throw 'returned quote native class';}"#);
}
#[test]
fn quote_interface_dynamic_connection_template_parking_and_inert_fallback_keep_authority(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml';for(var tag of ['q','blockquote']){var x=doc.createElementNS(html,tag);x.setAttribute('title','A\ud800Z');x.appendChild(doc.createTextNode('Fallback'));var first=x.firstChild,attr=x.getAttributeNode('title'),list=x.childNodes;document.body.appendChild(x);if(!(x instanceof HTMLQuoteElement)||x.ownerDocument!==document||x.firstChild!==first||x.getAttributeNode('title')!==attr||attr.value!=='A\ud800Z'||x.childNodes!==list)throw 'actual quote connection';var leaf=x.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(!(leaf instanceof HTMLQuoteElement)||leaf.parentNode!==template.content||leaf.ownerDocument!==template.content.ownerDocument||leaf.getAttribute('title')!=='A\ud800Z')throw 'parked quote class';var detached=doc.createElementNS(html,tag);detached.appendChild(doc.createTextNode('Before'));var old=detached.firstChild;detached.textContent='After\udfff';if(detached.textContent!=='After\udfff'||old.parentNode!==null||!(detached instanceof HTMLQuoteElement))throw 'inert quote fallback';}"#);
}
#[test]
fn quote_interface_child_saved_clone_origin_refusal_preserves_source_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var q=document.getElementById('q'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,C=child.HTMLQuoteElement,saved=child.Node.prototype.cloneNode,copy=saved.call(q,true);if(C===HTMLQuoteElement||C.prototype===HTMLQuoteElement.prototype||Object.getPrototypeOf(C)!==child.HTMLElement||!(copy instanceof HTMLQuoteElement)||copy.textContent!=='Inline')throw 'owner quote interface and captured clone';"#);p.set_location(&crate::navigation::address("https://other-quote-interface.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let e=p.runtime.execute("saved.call(q,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.set_location(&crate::navigation::address("https://quote-interface.test/dir/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"var again=saved.call(q,true);if(!(again instanceof HTMLQuoteElement)||again.textContent!=='Inline'||again===q)throw 'quote clone origin recovery';");
}
#[test]
fn quote_interface_existing_blockquote_raw_name_authority_and_new_q_guard_stay_distinct(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="q"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("name".into()),value:DomString::from("seed".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var q=document.getElementById('q'),attr=q.getAttributeNode('name'),b=document.getElementById('block'),watch=new MutationObserver(function(){});watch.observe(q,{attributes:true});");for code in [r"q.setAttribute('name','A\ud800Z');",r"attr.value='A\ud800Z';",r"attr.nodeValue='A\ud800Z';",r"attr.textContent='A\ud800Z';"]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Unpaired")||e.contains("requires")||e.contains("support"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='seed'||watch.takeRecords().length)throw 'raw q name has no prefix';");}run(&mut d,&mut f,&mut p,r"b.setAttribute('name','B\ud800Z');var copy=b.cloneNode(false);if(b.getAttribute('name')!=='B\ud800Z'||copy.getAttribute('name')!=='B\ud800Z'||document.getElementsByName('B\ud800Z')[0]!==b||!(copy instanceof HTMLQuoteElement))throw 'existing blockquote raw name authority';q.setAttribute('title','recovered');if(q.title!=='recovered'||watch.takeRecords().length!==1)throw 'fresh quote metadata recovery';");
}

#[test]
fn quote_interface_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["q","blockquote"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById(which==='q'?'q':'block');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.setAttribute('title','exact');source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.setAttribute('title','exact');source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('title');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('title')!==oldValue||watch.takeRecords().length)throw 'atomic quote lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('title')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.getAttribute('title')!==source.getAttribute('title')||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}



#[test]
fn quote_interface_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["q","blockquote"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.setAttribute('title','exact');source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('title');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('title')!==attr||source.getAttribute('title')!=='exact'||source.parentNode!==target)throw 'reserved native quote connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}



#[test]
fn quote_interface_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="q"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('q'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','q'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.getAttribute('cite')!=='../one')throw 'active content copy guard';");}
}


